<script setup>
import { ref, computed } from 'vue';
import InlineVideo from './InlineVideo.vue';
import ContextualProducts from './ContextualProducts.vue';
import SocialActions from './SocialActions.vue';
const props=defineProps({post:Object,products:{type:Array,default:()=>[]},comments:{type:Array,default:()=>[]},interaction:{type:Object,default:()=>({})},detail:Boolean});
const paused=ref(false);const linked=computed(()=>props.products.length?props.products:props.post.products || []);
</script>
<template><div class="editorial-grid"><ContextualProducts class="left-rail" :products="linked" :paused="paused" label="Para esta ideia"/><article class="editorial-story"><header class="story-heading"><span class="eyebrow">{{post.category || ({recipe:'Receita',news:'Notícia',video:'Vídeo'}[post.type])}}</span><h1 v-if="detail">{{post.title}}</h1><h2 v-else><a :href="`/blog/${post.slug}`">{{post.title}}</a></h2><p v-if="!post.video_url">{{post.excerpt}}</p></header><InlineVideo v-if="post.video_url" :src="post.video_url" :poster="post.poster_url" :captions="post.captions_url"/><div v-else-if="post.poster_url" class="story-poster"><img :src="post.poster_url" :alt="post.title"></div><div class="mobile-products"><ContextualProducts :products="linked" :paused="paused" label="Produtos nesta ideia"/></div><div class="story-copy"><button v-if="linked.length" class="motion-control" :aria-pressed="paused" @click="paused=!paused">{{paused?'Retomar movimento':'Pausar movimento'}}</button><p v-if="post.video_url" class="excerpt">{{post.excerpt}}</p><div class="plain-body" v-if="detail">{{post.body}}</div><a v-else :href="`/blog/${post.slug}`" class="read-more">Ler publicação completa →</a><p v-if="post.source_url" class="muted">Fonte: <a :href="post.source_url" rel="noopener noreferrer">{{post.source_name || 'Consultar fonte'}}</a></p><SocialActions v-if="detail" :post="post" :interaction="interaction"/><section v-if="detail" class="comments"><h2>Conversa</h2><p v-if="!comments.length" class="muted">Ainda não há comentários aprovados.</p><article v-for="c in comments" :key="c.id"><strong>{{c.display_name}}</strong><p class="plain-body">{{c.body}}</p></article></section></div></article><ContextualProducts class="right-rail" :products="[...linked].reverse()" :paused="paused" label="Mais para esta ideia"/></div></template>
